SIA_st.name='SIA'; 
SIA_st.lat=34.09;
SIA_st.lon=-110.94;
SIA_st.alt=1600;
%%
SIA_rd=read_betsy('sierraancha_head',SIA_st.name);
%%
datevec(SIA_rd.Time(1)) %[output:2680dec0]
datevec(SIA_rd.Time(end)) %[output:0e3018b4]
prctile(SIA_rd.U_S,[5, 50, 95]) %[output:637d623a]
plotFigControl(SIA_rd,SIA_st.name); %[output:87c193a5] %[output:0c3b6fab] %[output:9693e6ac] %[output:620cc3b1] %[output:526f7b5b] %[output:83052612] %[output:16a2f491] %[output:16a7b7a8] %[output:4067d7f5]
% 1 size cut, 
% sc: ok, clear seasonal cycle, max in summer-autumn, some negatives
%[text] % lambdaSC=\[450;550;700\]\*ones(1,4); % lambdaAE3=\[467;530;660\]\*ones(1,4); % lambdaAE7=\[370 470 520 590 660 880 950\]; % SIA\_cal=compute\_exp\_SSA(SIA\_rd,lambdaSC, lambdaAE3); % plotFigControl\_cal(SIA\_cal, SIA\_st.name);
%%
%Questions:
%problems:
%rupture in June 2006 ??
%%
SIA_tr=timetable(SIA_rd.Time);
% begin at the beginning of a year:2001
%end year: 2009
%ONLY 9 y

SIA_tr.BsG_S=SIA_rd.BsG_S;
% dry: OK
%otherwise seems ok
%%
% 2026
[SIA_result_MK,SIA_result_LMSlog,SIA_result_LMSlin]=all_trend_STN(SIA_tr,SIA_st); %[output:081bb14e] %[output:61aa3687] %[output:3bb8f66c] %[output:8cc6c0fc] %[output:376a2c3d] %[output:4dee0a59] %[output:6eab4344]

writetable(SIA_result_MK,'SIA_res_MK_present_10y.txt'); %, 'delimiter',',' )
writetable(SIA_result_LMSlog,'SIA_res_LMSlog.txt'); 
writetable(SIA_result_LMSlin,'SIA_res_LMSlin.txt'); 
plot_10y_in_two(SIA_result_MK, SIA_st,'y'); %[output:8530cb28] %[output:44c0d631]
%%
 timetable_to_netcdf(SIA_tr,'SIA_tr_def.nc'); %[output:03304f92]

